11	method Find(a: array<int>, key: int) returns (i: int)
12	   requires a != null;
13	   // if i is non-negative then 
14	   ensures 0 <= i ==> (// (1) i is smaller than the length of a
15	                       i < a.Length && 
16	                       // (2) key is at position i in a
17	                       a[i] == key && 
18	                       // (3) i is the smallest position where key appears
19	                       forall k :: 0 <= k < i ==> a[k] != key
20	                      );
21	   // if index is negative then
22	   ensures i < 0 ==> 
23	           // a does not contain key
24	           forall k :: 0 <= k < a.Length ==> a[k] != key;
25	{
26	   i := 0;
27	   while (i < a.Length)
28	     decreases a.Length - i;
29	     invariant 0 <= i <= a.Length;
30	     // key is at none of the positions seen so far
31	   {
32	      if (a[i] == key) { return; }
33	      i := i + 1;
34	   }
35	   i := -1;
36	}
37	
